	public void unAssignAircraftOrder( UnAssignAircraftOrderFromPurchaseAgreementCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignAircraftOrder(command.getPurchaseAgreementId());
	}
	




